// src/context/AuthContext.js
import React, { createContext, useContext, useState, useEffect } from "react";
import axios from "axios";

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(() => {
    const savedUser = localStorage.getItem("user");
    return savedUser ? JSON.parse(savedUser) : null;
  });

  const [token, setToken] = useState(() => localStorage.getItem("token"));

  // Attach token to axios if present
  useEffect(() => {
    if (token) {
      axios.defaults.headers.common["Authorization"] = `Bearer ${token}`;
    } else {
      delete axios.defaults.headers.common["Authorization"];
    }
  }, [token]);

  // ✅ Login function
  const login = async (username, password) => {
    try {
      const response = await axios.post("/api/auth/login", { username, password });
      console.log('Full login response:', response.data); // Added for debugging

      const { token: newToken, user, status, error } = response.data;

      if (status === "PENDING_VERIFICATION") {
        throw new Error("Account is not verified yet. Please wait for admin approval.");
      }

      if (status === "ACCOUNT_DISABLED") {
        throw new Error("Account is disabled. Please contact admin.");
      }

      if (newToken && user) {
        setToken(newToken);
        localStorage.setItem("token", newToken);

        const userData = {
          username: user.username,
          email: user.email,
          roles: user.roles || [],
        };

        setUser(userData);
        localStorage.setItem("user", JSON.stringify(userData));

        axios.defaults.headers.common["Authorization"] = `Bearer ${newToken}`;
        return { success: true, data: userData };
      }

      // If missing keys, log and throw specific error
      console.error('Invalid response structure:', response.data);
      throw new Error(error || "Invalid response from server: missing token or user data");
    } catch (error) {
      console.error("Login error:", error);
      if (error.response) {
        throw new Error(error.response.data?.error || "Login failed");
      }
      throw error;
    }
  };

  // ✅ Register function
  const register = async (username, email, password) => {
    try {
      const response = await axios.post("/api/auth/register", {
        username,
        email,
        password,
      });

      return response.data; // success message or created user
    } catch (error) {
      console.error("Register error:", error);
      if (error.response) {
        throw new Error(error.response.data?.error || "Registration failed");
      }
      throw error;
    }
  };

  // ✅ Logout function
  const logout = () => {
    setUser(null);
    setToken(null);
    localStorage.removeItem("user");
    localStorage.removeItem("token");
    delete axios.defaults.headers.common["Authorization"];
  };

  // ✅ Role helpers
  const hasRole = (role) => user?.roles?.includes(role) || false;
  const isVendor = () => hasRole("ROLE_VENDOR");
  const isAdmin = () => hasRole("ROLE_ADMIN");

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        login,
        register, // 👈 now available
        logout,
        isVendor,
        isAdmin,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
